CREATE TABLE IF NOT EXISTS internal_voucher_evidence (
  document_id INTEGER PRIMARY KEY REFERENCES documents(id),
  bank_transaction_id INTEGER NOT NULL UNIQUE REFERENCES bank_transactions(id),
  accounting_rationale TEXT NOT NULL CHECK(length(trim(accounting_rationale)) BETWEEN 1 AND 2000),
  prepared_by TEXT NOT NULL CHECK(length(trim(prepared_by)) BETWEEN 1 AND 256),
  prepared_by_program TEXT NOT NULL CHECK(length(trim(prepared_by_program)) BETWEEN 1 AND 256),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER internal_voucher_evidence_no_update BEFORE UPDATE ON internal_voucher_evidence BEGIN SELECT RAISE(ABORT, 'internal voucher evidence is append-only'); END;
CREATE TRIGGER internal_voucher_evidence_no_delete BEFORE DELETE ON internal_voucher_evidence BEGIN SELECT RAISE(ABORT, 'internal voucher evidence is append-only'); END;
CREATE TRIGGER internal_voucher_document_no_update BEFORE UPDATE ON documents WHEN OLD.document_type = 'internal_voucher' BEGIN SELECT RAISE(ABORT, 'internal voucher documents are append-only'); END;
CREATE TRIGGER internal_voucher_document_no_delete BEFORE DELETE ON documents WHEN OLD.document_type = 'internal_voucher' BEGIN SELECT RAISE(ABORT, 'internal voucher documents are append-only'); END;
CREATE TRIGGER internal_voucher_bank_no_update BEFORE UPDATE ON bank_transactions WHEN EXISTS(SELECT 1 FROM internal_voucher_evidence WHERE bank_transaction_id = OLD.id) BEGIN SELECT RAISE(ABORT, 'bank transaction backing an internal voucher is append-only'); END;
